/*
 * Zephyr RTOS ADC example with hardware oversampling.
 *
 * Board: nrf52840dk/nrf52840
 *
 * This program:
 *  - Obtains the ADC device using the alias "adc0".
 *  - Configures channel 0 with gain = 1, internal reference and default acquisition time.
 *  - Sets up a sequence that uses hardware oversampling (2^4 = 16 samples) and 12‑bit resolution.
 *  - Reads the ADC in a loop, printing the raw sample value each second.
 */

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/sys/util.h>   /* BIT() macro */

/* ADC device (alias must be defined in the board's devicetree) */
#define ADC_NODE DT_ALIAS(adc0)
static const struct device *adc_dev = DEVICE_DT_GET(ADC_NODE);

/* Buffer to hold a single sample */
static int16_t sample_buffer[1];

void main(void)
{
    int ret;

    if (!device_is_ready(adc_dev)) {
        printk("ADC device %s is not ready\n", adc_dev->name);
        return;
    }

    /* Channel configuration */
    struct adc_channel_cfg channel_cfg = {
        .gain = ADC_GAIN_1,
        .reference = ADC_REF_INTERNAL,
        .acquisition_time = ADC_ACQ_TIME_DEFAULT,
        .channel_id = 0,
        /* nRF specific: select AIN0 as the positive input */
        .input_positive = NRF_SAADC_INPUT_AIN0,
        .input_negative = NRF_SAADC_INPUT_DISABLED,
    };

    ret = adc_channel_setup(adc_dev, &channel_cfg);
    if (ret) {
        printk("Failed to setup ADC channel (err %d)\n", ret);
        return;
    }

    /* Sequence configuration */
    struct adc_sequence sequence = {
        .channels = BIT(0),                     /* Use channel 0 */
        .buffer = sample_buffer,
        .buffer_size = sizeof(sample_buffer),
        .resolution = 12,                       /* 12‑bit resolution */
        .oversampling = 4,                      /* 2^4 = 16 samples averaged */
    };

    printk("Starting ADC read loop (hardware oversampling 16x)...\n");

    while (1) {
        ret = adc_read(adc_dev, &sequence);
        if (ret) {
            printk("ADC read error (err %d)\n", ret);
        } else {
            printk("Raw sample: %d\n", sample_buffer[0]);
        }

        k_sleep(K_SECONDS(1));
    }
}
